import sympy as sp

x, y, z, u, v = sp.symbols("x y z u v")


def gamma_parabola(uu):
    return uu, uu**2


def tau_of_gamma(g1, g2, uu, mu):
    return sp.expand(mu * sp.diff(g1, uu)), sp.expand(mu * sp.diff(g2, uu))


def wronskian_gamma(g1, g2, uu):
    return sp.expand(
        sp.diff(g1, uu) * sp.diff(g2, uu, 2)
        - sp.diff(g2, uu) * sp.diff(g1, uu, 2)
    )


def is_admissible(g1, g2, uu):
    determinant = wronskian_gamma(g1, g2, uu)
    return bool(
        sp.Poly(determinant, uu).degree() == 0 and determinant != 0
    ), determinant


def poisson_bracket(first, second, uu, vv):
    return sp.expand(
        sp.diff(first, uu) * sp.diff(second, vv)
        - sp.diff(first, vv) * sp.diff(second, uu)
    )


def is_poisson_admissible(first, second, uu, vv):
    determinant = poisson_bracket(first, second, uu, vv)
    return bool(determinant != 0), determinant


def hyperbolic_poisson_pair_2_3(uu, vv):
    return uu**2 - vv, uu * vv - sp.Rational(2, 3) * uu**3


def hyperbolic_companion_h2(h1ex, constant_symbol, uu):
    return sp.expand(
        constant_symbol - sp.integrate(uu * sp.diff(h1ex, uu), uu)
    )


def make_poly_xy(prefix, degree_x, degree_y, xv, yv):
    coefficients = [
        sp.Symbol(f"{prefix}_{i}_{j}")
        for i in range(degree_x + 1)
        for j in range(degree_y + 1)
    ]
    expression = sum(
        (
            sp.Symbol(f"{prefix}_{i}_{j}") * xv**i * yv**j
            for i in range(degree_x + 1)
            for j in range(degree_y + 1)
        ),
        sp.Integer(0),
    )
    return sp.expand(expression), coefficients


def make_poly_u(prefix, degree, uu):
    coefficients = [
        sp.Symbol(f"{prefix}_{i}") for i in range(degree + 1)
    ]
    expression = sum(
        (
            coefficient * uu**i
            for i, coefficient in enumerate(coefficients)
        ),
        sp.Integer(0),
    )
    return expression, coefficients


def build_Fstar_pair(
    base1,
    base2,
    fex,
    gex,
    h1ex,
    h2ex,
    Pex,
    Qex,
    xv,
    yv,
    zv,
    uu,
    vv,
):
    uex = yv + fex
    vex = gex
    Xex = Pex + zv * Qex
    substitutions = {uu: uex, vv: vex}
    D1 = sp.expand(base1.subs(substitutions, simultaneous=True))
    D2 = sp.expand(base2.subs(substitutions, simultaneous=True))
    Fs1 = sp.expand(D1 - Xex * h1ex.subs(uu, uex))
    Fs2 = sp.expand(D2 - Xex * h2ex.subs(uu, uex))
    return uex, vex, Xex, D1, D2, Fs1, Fs2


def negative_laurent_coefficients(expression, xv):
    expression = sp.cancel(expression)
    numerator, denominator = sp.fraction(expression)
    coefficient, remainder = denominator.as_independent(
        xv, as_Add=False
    )
    if remainder != 1 and not remainder.is_Pow and remainder != xv:
        raise ValueError(
            "Expression is not a Laurent polynomial in the selected variable"
        )
    if remainder == xv:
        order = 1
    elif remainder == 1:
        order = 0
    else:
        exponent = remainder.as_base_exp()[1]
        if exponent.is_integer is not True:
            raise ValueError("Nonintegral Laurent exponent")
        order = int(exponent)
    if sp.simplify(coefficient) == 0:
        raise ZeroDivisionError("Zero denominator")
    polynomial = sp.Poly(sp.expand(numerator), xv)
    return {
        degree - order: sp.expand(value / coefficient)
        for (degree,), value in polynomial.terms()
        if degree < order and value != 0
    }


def max_negative_x_order(expression, xv):
    coefficients = negative_laurent_coefficients(expression, xv)
    return max((-degree for degree in coefficients), default=0)


def unique_equations(expressions):
    result = []
    seen = set()
    for expression in expressions:
        reduced = sp.factor(expression)
        if reduced != 0 and sp.srepr(reduced) not in seen:
            seen.add(sp.srepr(reduced))
            result.append(reduced)
    return result


def pole_cancellation_equations(expressions, xv, split_vars):
    equations = []
    for expression in expressions:
        for coefficient in negative_laurent_coefficients(
            expression, xv
        ).values():
            equations.extend(
                sp.Poly(coefficient, *split_vars).coeffs()
                if split_vars
                else [coefficient]
            )
    return unique_equations(equations)


def solve_eqs(equations, unknowns):
    equations = unique_equations(equations)
    unknowns = list(dict.fromkeys(unknowns))
    if not equations:
        return {"status": "free", "data": [{}]}
    if not unknowns:
        return {
            "status": (
                "unsat"
                if any(
                    sp.simplify(equation) != 0
                    for equation in equations
                )
                else "free"
            ),
            "data": [],
        }
    basis = sp.groebner(equations, *unknowns, order="grevlex")
    if any(
        polynomial.total_degree() == 0
        and polynomial.as_expr() != 0
        for polynomial in basis.polys
    ):
        return {"status": "unsat", "data": basis}
    solutions = sp.solve(
        [polynomial.as_expr() for polynomial in basis.polys],
        unknowns,
        dict=True,
    )
    return {
        "status": "solved" if solutions else "unresolved",
        "data": solutions if solutions else basis,
    }


def verify_solution(equations, solution):
    return all(
        sp.simplify(equation.subs(solution)) == 0
        for equation in equations
    )


def finalize_expression(expression):
    return sp.expand(sp.cancel(expression))


def is_polynomial_in(expression, generators):
    try:
        sp.Poly(sp.cancel(expression), *generators)
        return True
    except sp.PolynomialError:
        return False


def jacobian_report(first, second, third, xv, yv, zv):
    matrix = sp.Matrix(
        [
            expression.diff(variable)
            for expression in (first, second, third)
            for variable in (xv, yv, zv)
        ]
    ).reshape(3, 3)
    determinant = sp.factor(matrix.det())
    is_constant_nonzero = bool(
        determinant != 0
        and not determinant.free_symbols.intersection(
            {xv, yv, zv}
        )
    )
    return matrix, determinant, is_constant_nonzero


def hyperbolic_collision_2_3():
    return {
        "u1": sp.Integer(1),
        "v1": sp.Rational(2, 3),
        "u2": sp.Integer(-1),
        "v2": sp.Rational(2, 3),
