    }


def lift_collision_to_3d(
    collision, fex, gex, Pex, Qex, solution, xv, yv
):
    result = []
    parameter_pairs = (
        (collision["u1"], collision["v1"]),
        (collision["u2"], collision["v2"]),
    )
    for uvalue, vvalue in parameter_pairs:
        point = None
        for root in sp.solve(
            sp.Eq(gex.subs(solution), vvalue), xv
        ):
            if root == 0:
                continue
            yvalue = sp.simplify(
                uvalue - fex.subs(solution).subs(xv, root)
            )
            substitutions = {xv: root, yv: yvalue}
            Pvalue = sp.simplify(
                Pex.subs(solution).subs(substitutions)
            )
            Qvalue = sp.simplify(
                Qex.subs(solution).subs(substitutions)
            )
            if Qvalue != 0:
                point = (
                    root,
                    yvalue,
                    sp.simplify(-Pvalue / Qvalue),
                )
                break
            if Pvalue == 0:
                point = (root, yvalue, sp.Integer(0))
                break
        result.append(point)
    return result


def collision_values_equal(expressions, points, xv, yv, zv):
    if len(points) != 2 or any(
        point is None for point in points
    ):
        return False, []
    values = [
        tuple(
            sp.simplify(
                expression.subs(
                    dict(zip((xv, yv, zv), point))
                )
            )
            for expression in expressions
        )
        for point in points
    ]
    distinct = any(
        sp.simplify(a - b) != 0
        for a, b in zip(*points)
    )
    equal_values = all(
        sp.simplify(a - b) == 0
        for a, b in zip(*values)
    )
    return bool(distinct and equal_values), values


def run_pipeline():
    base1, base2 = hyperbolic_poisson_pair_2_3(u, v)
    admissible, bracket = is_poisson_admissible(
        base1, base2, u, v
    )
    fex = 1 / x
