    h1ex, h1syms = make_poly_u("p", 2, u)
    h2const = sp.Symbol("q_0")
    h2ex = hyperbolic_companion_h2(
        h1ex, h2const, u
    )
    Pex, Psyms = make_poly_xy("r", 2, 1, x, y)
    Qex = x**5 / 2
    uex, vex, Xex, D1, D2, Fs1, Fs2 = (
        build_Fstar_pair(
            base1,
