    unknowns = h1syms + [h2const] + Psyms
    obstruction_first = sp.expand(
        negative_laurent_coefficients(
            Fs1, x
        ).get(-2, 0)
    ).coeff(z, 0)
    obstruction_second = sp.expand(
        negative_laurent_coefficients(
            Fs2, x
        ).get(-3, 0)
    ).coeff(z, 0)
    obstruction_identity = sp.simplify(
        obstruction_second
